113	impl ComponentPreview {
114	    pub fn new(
115	        workspace: WeakEntity<Workspace>,
116	        project: Entity<Project>,
117	        language_registry: Arc<LanguageRegistry>,
118	        user_store: Entity<UserStore>,
119	        selected_index: impl Into<Option<usize>>,
120	        active_page: Option<PreviewPage>,
121	        window: &mut Window,
122	        cx: &mut Context<Self>,
123	    ) -> anyhow::Result<Self> {
124	        let component_registry = Arc::new(components());
125	        let sorted_components = component_registry.sorted_components();
126	        let selected_index = selected_index.into().unwrap_or(0);
127	        let active_page = active_page.unwrap_or(PreviewPage::AllComponents);
128	        let filter_editor = cx.new(|cx| InputField::new(window, cx, "Find components or usages…"));
129	
130	        let component_list = ListState::new(
131	            sorted_components.len(),
132	            gpui::ListAlignment::Top,
133	            px(1500.0),
134	        );
135	
136	        let mut component_preview = Self {
137	            active_page,
138	            reset_key: 0,
139	            component_list,
140	            entries: Vec::new(),
141	            component_map: component_registry.component_map(),
142	            components: sorted_components,
143	            cursor_index: selected_index,
144	            filter_editor,
145	            filter_text: String::new(),
146	            focus_handle: cx.focus_handle(),
147	            language_registry,
148	            nav_scroll_handle: UniformListScrollHandle::new(),
149	            project,
150	            user_store,
151	            workspace,
152	            workspace_id: None,
153	            _view_scroll_handle: ScrollHandle::new(),
154	        };
155	
156	        if component_preview.cursor_index > 0 {
157	            component_preview.scroll_to_preview(component_preview.cursor_index, cx);
158	        }
159	
160	        component_preview.update_component_list(cx);
161	
162	        let focus_handle = component_preview.filter_editor.read(cx).focus_handle(cx);
163	        window.focus(&focus_handle, cx);
164	
165	        Ok(component_preview)
166	    }
167	
168	    pub fn active_page_id(&self, _cx: &App) -> ActivePageId {
169	        match &self.active_page {
170	            PreviewPage::AllComponents => ActivePageId::default(),
171	            PreviewPage::Component(component_id) => ActivePageId(component_id.0.to_string()),
172	        }
173	    }
174	
175	    fn scroll_to_preview(&mut self, ix: usize, cx: &mut Context<Self>) {
176	        self.component_list.scroll_to_reveal_item(ix);
177	        self.cursor_index = ix;
178	        cx.notify();
179	    }
180	
181	    fn set_active_page(&mut self, page: PreviewPage, cx: &mut Context<Self>) {
182	        if self.active_page == page {
183	            // Force the current preview page to render again
184	            self.reset_key = self.reset_key.wrapping_add(1);
185	        } else {
186	            self.active_page = page;
187	            cx.emit(ItemEvent::UpdateTab);
188	        }
189	        cx.notify();
190	    }
191	
192	    fn filtered_components(&self) -> Vec<ComponentMetadata> {
193	        if self.filter_text.is_empty() {
194	            return self.components.clone();
195	        }
196	
197	        let filter = self.filter_text.to_lowercase();
198	        self.components
199	            .iter()
200	            .filter(|component| {
201	                let component_name = component.name().to_lowercase();
202	                let scope_name = component.scope().to_string().to_lowercase();
203	                let description = component.description().to_lowercase();
204	
205	                component_name.contains(&filter)
206	                    || scope_name.contains(&filter)
207	                    || description.contains(&filter)
208	            })
209	            .cloned()
210	            .collect()
211	    }
212	
213	    fn scope_ordered_entries(&self) -> Vec<PreviewEntry> {
214	        use collections::HashMap;
215	
216	        let mut scope_groups: HashMap<
217	            ComponentScope,
218	            Vec<(ComponentMetadata, Option<Vec<usize>>)>,
219	        > = HashMap::default();
220	        let lowercase_filter = self.filter_text.to_lowercase();
221	
222	        for component in &self.components {
223	            if self.filter_text.is_empty() {
224	                scope_groups
225	                    .entry(component.scope())
226	                    .or_insert_with(Vec::new)
227	                    .push((component.clone(), None));
228	                continue;
229	            }
230	
231	            // let full_component_name = component.name();
232	            let scopeless_name = component.scopeless_name();
233	            let scope_name = component.scope().to_string();
234	            let description = component.description();
235	
